<?php
session_start();if(!isset($_SESSION['user_id'])){header('Location: login.html');exit;}
require __DIR__.'/db.php';require __DIR__.'/artwork-common.php';$uid=(int)$_SESSION['user_id'];if(!artworkIsStudent($conn,$uid)){http_response_code(403);exit('Student access only.');}
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Invalid artwork.');}
$s=$conn->prepare("SELECT artwork_id,title,description,category_id,status FROM artworks WHERE artwork_id=? AND user_id=? AND LOWER(status) IN ('pending','rejected')");$s->bind_param('ii',$id,$uid);$s->execute();$art=$s->get_result()->fetch_assoc();$s->close();if(!$art){http_response_code(404);exit('Artwork is unavailable for editing.');}
$cats=$conn->query('SELECT category_id,category_name FROM categories WHERE is_active=1 ORDER BY category_name');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Artwork | MIRA</title><link rel="stylesheet" href="artwork-workflow.css"><link rel="stylesheet" href="mira-student-nav.css?v=2"><script src="theme.js" defer></script></head><body class="mira-workflow"><?php require __DIR__.'/mira-student-nav.php'; ?><main class="workflow-wrap"><div class="workflow-heading"><p class="overline">MY MIRA STUDIO</p><h1>Edit artwork</h1><p>Save changes, then resubmit rejected artworks from Submission Tracking.</p></div><?php if(($_GET['error']??'')==='1'): ?><p class="notice error">Please check all fields and image requirements.</p><?php endif; ?><form class="form-card" action="update-artwork.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= artworkEscape(artworkCsrf()) ?>"><input type="hidden" name="artwork_id" value="<?= (int)$art['artwork_id'] ?>"><label for="title">Title</label><input id="title" name="title" maxlength="200" required value="<?= artworkEscape($art['title']) ?>"><label for="category">Category</label><select id="category" name="category_id" required><?php foreach($cats as $cat): ?><option value="<?= (int)$cat['category_id'] ?>" <?= (int)$art['category_id']===(int)$cat['category_id']?'selected':'' ?>><?= artworkEscape($cat['category_name']) ?></option><?php endforeach; ?></select><label for="description">Description</label><textarea id="description" name="description" maxlength="3000" rows="6" required><?= artworkEscape($art['description']) ?></textarea><label for="artwork_image">Replace image (optional; JPG, PNG, WebP; max 5 MB)</label><input id="artwork_image" type="file" name="artwork_image" accept="image/jpeg,image/png,image/webp"><p>Leave the image field empty to keep the current image.</p><div class="form-footer"><a class="outline-btn" href="my-artworks.php">Cancel</a><button class="primary-btn" type="submit">Save changes</button></div></form></main></body></html>
